@RestController class ApiController { @GetMapping("/greeting") String greeting() { return "greeting"; } }
-> zwrocony String trafia WPROST do ciala odpowiedzi HTTP jako tekst

@RestController
class ApiController {

    @GetMapping("/api/greeting")
    Greeting greeting() {
        return new Greeting("Witaj!", "JavaQuest");
    }
}

record Greeting(String message, String author) {}

// GET /api/greeting zwraca:
// {"message":"Witaj!","author":"JavaQuest"}
